CREATE TABLE IF NOT EXISTS products (product_id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL,description TEXT,price REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'USD',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,image_url TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory (inventory_id TEXT PRIMARY KEY,product_id TEXT NOT NULL,variant_id TEXT NOT NULL,variant_label TEXT,size TEXT,stock_on_hand INTEGER NOT NULL DEFAULT 0,low_stock_threshold INTEGER NOT NULL DEFAULT 3,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(product_id,variant_id,size));
CREATE TABLE IF NOT EXISTS orders (order_id TEXT PRIMARY KEY,keyword TEXT,source TEXT,currency TEXT NOT NULL DEFAULT 'USD',subtotal_amount REAL NOT NULL,delivery_method TEXT,delivery_fee REAL NOT NULL DEFAULT 0,total_amount REAL NOT NULL,payment_status TEXT NOT NULL DEFAULT 'created',paynow_status TEXT,fulfilment_status TEXT NOT NULL DEFAULT 'unfulfilled',shipment_status TEXT NOT NULL DEFAULT 'not_shipped',tracking_number TEXT,customer_name TEXT,customer_phone TEXT,customer_email TEXT,delivery_address TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,paid_at TEXT);
CREATE TABLE IF NOT EXISTS order_items (item_id TEXT PRIMARY KEY,order_id TEXT NOT NULL,product_id TEXT NOT NULL,product_name TEXT NOT NULL,variant_id TEXT,variant_label TEXT,size TEXT,quantity INTEGER NOT NULL,unit_price REAL NOT NULL,line_total REAL NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inventory_movements (movement_id TEXT PRIMARY KEY,product_id TEXT NOT NULL,variant_id TEXT,size TEXT,quantity_change INTEGER NOT NULL,reason TEXT,order_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_attempts (attempt_id TEXT PRIMARY KEY,order_id TEXT NOT NULL,provider TEXT NOT NULL,request_amount REAL,provider_response TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
